export interface Link {
    id: number;
    slug: string;
    originalUrl: string;
    clicks: number;
    createdAt: Date;
}

export class LinkService {
    private links: Link[] = [];

    constructor() {
        try {
            const saved = localStorage.getItem('shortLinks');
            if (saved) this.links = JSON.parse(saved);
        } catch (e) { }
    }

    createLink(originalUrl: string): string {
        const slug = generateSlug();
        const link: Link = { id: this.links.length + 1, slug, originalUrl, clicks: 0, createdAt: new Date() };
        this.links.push(link);
        localStorage.setItem('shortLinks', JSON.stringify(this.links));
        return link.slug;
    }

    getLink(slug: string): string | null {
        const link = this.links.find(l => l.slug === slug);
        if (link) {
            link.clicks++;
            localStorage.setItem('shortLinks', JSON.stringify(this.links));
            return link.originalUrl;
        }
        return null;
    }

    deleteLink(slug: string): void {
        this.links = this.links.filter(l => l.slug !== slug);
        localStorage.setItem('shortLinks', JSON.stringify(this.links));
    }
}

function generateSlug() {
    const unique = 'abcdefghijklmnopqrstuvwxyz0123456789';
    return Array.from({ length: 6 }, () => unique[Math.floor(Math.random() * unique.length)]).join('');
}

