export function render(container: HTMLElement) {
    container.innerHTML = `
        <div class="flex items-center gap-4">
            <div class="w-96">
                <div class="p-6 bg-gray-800 rounded">
                    <div class="flex items-center justify-between mb-4">
                        <div class="text-2xl text-white font-semibold">🔗 Shorten URL</div>
                        <button class="px-4 py-2 rounded bg-primary text-white" onclick="copyShortUrl()">📋 Copy</button>
                    </div>
                    <div class="mb-4">
                        <label class="block text-gray-400 mb-2">Original URL</label>
                        <input id="originalUrl" class="w-full px-4 py-2 rounded text-gray-300" placeholder="Enter the full URL to shorten">
                    </div>
                    <div class="mb-4">
                        <label class="block text-gray-400 mb-2">Short ID</label>
                        <input id="shortId" class="w-full px-4 py-2 rounded text-gray-300" placeholder="Optional custom ID">
                    </div>
                    <button class="w-full px-4 py-2 rounded bg-primary text-white" onclick="shorten()">Shorten</button>
                </div>
            </div>
            <div class="w-48">
                <div class="p-4 bg-gray-700 rounded">
                    <div class="text-white text-xl mb-2">🔗 Your Short URL</div>
                    <div id="shortUrlDisplay" class="text-white font-bold text-2xl mb-4"></div>
                    <button class="w-full px-4 py-2 rounded bg-secondary text-white" onclick="copyShortUrl()">📋 Copy</button>
                    <button class="w-full px-4 py-2 rounded bg-danger text-white" onclick="deleteShortUrl()">✕ Delete</button>
                </div>
            </div>
        </div>
        <div class="mt-8">
            <div class="p-6 bg-gray-800 rounded">
                <div class="text-white text-xl mb-4">🔗 Redirects</div>
                <div id="redirectsList" class="flex flex-col gap-2"></div>
            </div>
        </div>
    `;

    const originalInput = document.getElementById('originalUrl') as HTMLInputElement;
    const shortIdInput = document.getElementById('shortId') as HTMLInputElement;
    const shortUrlDisplay = document.getElementById('shortUrlDisplay') as HTMLSpanElement;
    const redirectsList = document.getElementById('redirectsList') as HTMLDivElement;

    const shortUrls: { original: string; short: string; clicks: number }[] = [];

    function shorten() {
        if (originalInput.value.trim() === '') return;
        const shortId = shortIdInput.value.trim();
        const original = originalInput.value.trim();

        if (shortId && shortUrls.some(u => u.short === shortId)) {
            alert('Short ID already exists');
            return;
        }

        const short = shortId || generateShort();
        const url = new URL(original);
        const shortUrl = `${document.location.origin}/s/${short}`;

        shortUrls.push({ original, short, clicks: 0 });
        updateRedirectsList();
        shortUrlDisplay.textContent = shortUrl;
        originalInput.value = '';
        shortIdInput.value = '';
    }

    function generateShort() {
        const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        let short = '';
        for (let i = 0; i < 6; i++) short += chars.charAt(Math.floor(Math.random() * chars.length));
        return short;
    }

    function updateRedirectsList() {
        redirectsList.innerHTML = shortUrls.map(u => {
            const clicks = u.clicks;
            return `<div class="flex items-center gap-2 mb-2">
                <span class="text-gray-300">${u.original} → <a href="${u.original}" target="_blank" class="text-primary hover:text-primary-200">${u.short}</a></span>
                <span class="text-gray-400 ml-2">(${clicks} clicks)</span>
            </div>`;
        }).join('');
    }

    function copyShortUrl() {
        const short = document.querySelector('a[href^="/s/"]');
        if (short) navigator.clipboard.writeText(short.href);
    }

    function deleteShortUrl() {
        shortUrls.length = 0;
        updateRedirectsList();
    }
}

