export function setupApiRoutes() {
    const stats: { [key: string]: { totalClicks: number; uniqueVisitors: number } } = {};

    const incrementClicks = (slug: string) => {
        if (stats[slug]) {
            stats[slug].totalClicks++;
            stats[slug].uniqueVisitors = Array.from(new Set([stats[slug].uniqueVisitors, 1])).length;
        }
    };

    const getStats = (slug: string) => stats[slug];

    return {
        incrementClicks,
        getStats,
    };
}

