export class LinkStore {
    private data: { [key: string]: { slug: string; originalUrl: string; clickCount: number; } } = {};

    public async save(link: { slug: string; originalUrl: string; clickCount: number; }): Promise<void> {
        this.data[link.slug] = link;
    }

    public async find(slug: string): Promise<{ slug: string; originalUrl: string; clickCount: number; } | null> {
        return this.data[slug] || null;
    }

    public async update(link: { slug: string; originalUrl: string; clickCount: number; }): Promise<void> {
        this.data[link.slug] = link;
    }
}
